<?php
declare(strict_types=1);
require __DIR__ . '/../../../../lib/app.php';
app_require_mode([0,1,2]);

/** Etiqueta uniforme con ayuda contextual accesible para formularios AJAX. */
function oferta_ayuda(string $ayuda,string $campo=''):string
{
    return '<span class="field-help" tabindex="0" role="button" data-bs-toggle="tooltip" data-bs-placement="top" title="'.app_escape($ayuda).'" aria-label="Ayuda'.($campo!==''?': '.app_escape($campo):'').'"><i class="bi bi-question-circle"></i></span>';
}
function oferta_label(string $titulo,string $ayuda,bool $obligatorio=false,string $clases=''):string
{
    $clase='form-label'.($clases!==''?' '.$clases:'');
    $texto=$obligatorio?'<span class="required">'.app_escape($titulo).'</span>':app_escape($titulo);
    return '<label class="'.$clase.'">'.$texto.' '.oferta_ayuda($ayuda,$titulo).'</label>';
}
$db=app_db();$id=app_int('id');
$record=$id?$db->one('SELECT * FROM ofertas WHERE id=?','i',[$id]):null;
if($id&&!$record){http_response_code(404);exit('Oferta inexistente.');}
$categories=$db->all('SELECT c.id,c.nombre,n.nombre nivel FROM catalogo_categorias c JOIN catalogo_niveles n ON n.id=c.nivel_id WHERE c.activo=1 AND c.admite_ofertas=1 ORDER BY n.orden,c.nombre');
$units=$db->all('SELECT id,nombre FROM unidades_academicas WHERE activo=1 ORDER BY nombre');
$modalities=$db->all('SELECT id,nombre FROM modalidades WHERE activo=1 ORDER BY orden');
$call=$id?$db->one("SELECT * FROM oferta_convocatorias WHERE oferta_id=? ORDER BY CASE estado WHEN 'abierta' THEN 0 WHEN 'programada' THEN 1 ELSE 2 END,anio DESC,id DESC LIMIT 1",'i',[$id]):null;
$plan=$id?$db->all('SELECT titulo,contenido,orden FROM oferta_plan_estudios WHERE oferta_id=? ORDER BY orden,id','i',[$id]):[];
?>
