<div class="col-md-2"><?=oferta_label('Duración','Cantidad correspondiente a la unidad seleccionada; por ejemplo, 4 años o 6 cuatrimestres.')?><input class="form-control" type="number" name="duracion_valor" min="0" max="9999" step="0.5" value="<?=app_escape($record['duracion_valor']??'')?>"></div><div class="col-md-3"><?=oferta_label('Unidad de duración','Unidad utilizada para expresar la duración total de la propuesta.')?><select class="form-select" name="duracion_unidad"><option value="">Sin especificar</option><?php foreach(['anios'=>'Años','cuatrimestres'=>'Cuatrimestres','meses'=>'Meses','semanas'=>'Semanas','horas'=>'Horas'] as $value=>$label):?><option value="<?=$value?>" <?=($record['duracion_unidad']??'')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-2"><?=oferta_label('Carga horaria','Cantidad total de horas establecida por el plan de estudios.')?><input class="form-control" type="number" name="carga_horaria" min="0" max="65535" value="<?=app_escape($record['carga_horaria']??'')?>"></div><div class="col-md-5"><?=oferta_label('Video de YouTube','Pegá la URL completa o el código de un video institucional relacionado con la oferta.')?><input class="form-control" name="youtube" maxlength="200" placeholder="https://www.youtube.com/watch?v=..." value="<?=app_escape($record['youtube_codigo']??'')?>"></div>
<div class="col-12"><?=oferta_label('Imagen de la oferta','Seleccioná una imagen JPG, PNG o WebP de hasta 8 MB.')?><div class="offer-image-editor"><div class="offer-image-preview <?=empty($record['imagen_url'])?'is-empty':''?>" id="offer-image-preview"><img src="<?=app_escape($record['imagen_url']??'')?>" alt="Vista previa"><span><i class="bi bi-image"></i> Sin imagen cargada</span></div><div class="d-flex flex-wrap gap-2"><label class="btn btn-outline-primary mb-0"><i class="bi bi-upload me-2"></i>Examinar imagen<input class="visually-hidden" type="file" id="offer-image-input" name="imagen" accept="image/jpeg,image/png,image/webp"></label><button class="btn btn-outline-danger <?=empty($record['imagen_url'])?'d-none':''?>" type="button" id="offer-image-remove"><i class="bi bi-trash me-2"></i>Quitar imagen</button></div><input type="hidden" name="quitar_imagen" id="offer-image-remove-value" value="0"></div></div>
<div class="col-md-3"><?=oferta_label('Estado de la oferta','Situación académica actual que verá el visitante: próxima, con inscripción abierta, en curso o cerrada.',true)?><select class="form-select" name="estado_oferta" required><?php foreach(['proximamente'=>'Próximamente','inscripcion_abierta'=>'Inscripción abierta','en_curso'=>'En curso','a_termino'=>'A término','cerrada'=>'Cerrada'] as $value=>$label):?><option value="<?=$value?>" <?=($record['estado_oferta']??'proximamente')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-3"><?=oferta_label('Publicación','Borrador no aparece en el portal; Publicada queda visible; Archivada se conserva sin mostrarse.',true)?><select class="form-select" name="estado_publicacion" required><?php foreach(['borrador'=>'Borrador','publicada'=>'Publicada','archivada'=>'Archivada'] as $value=>$label):?><option value="<?=$value?>" <?=($record['estado_publicacion']??'borrador')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-2"><?=oferta_label('Orden','Prioridad de presentación. Los valores menores aparecen primero.')?><input class="form-control" type="number" name="orden" min="0" max="65535" value="<?=(int)($record['orden']??0)?>"></div><div class="col-md-4 d-flex align-items-end"><label class="form-check mb-2"><input class="form-check-input" type="checkbox" name="destacada" value="1" <?=!empty($record['destacada'])?'checked':''?>><span class="form-check-label">Mostrar como oferta destacada <?=oferta_ayuda('Da mayor visibilidad a esta propuesta en los espacios destacados del portal.','Oferta destacada')?></span></label></div>
<div class="col-12"><hr><h3 class="h6">Convocatoria actual <span class="text-secondary fw-normal">(opcional)</span> <?=oferta_ayuda('Información de una apertura concreta de inscripciones. Puede dejarse vacía hasta definir fechas y cupos.','Convocatoria actual')?></h3></div><input type="hidden" name="convocatoria_id" value="<?=(int)($call['id']??0)?>"><div class="col-md-2"><?=oferta_label('Año','Año académico al que corresponde esta convocatoria.')?><input class="form-control" type="number" name="convocatoria_anio" min="2000" max="2100" value="<?=app_escape($call['anio']??'')?>"></div><div class="col-md-2"><?=oferta_label('Edición','Nombre breve para distinguir convocatorias del mismo año, por ejemplo: Primera o Cohorte 2027.')?><input class="form-control" name="convocatoria_edicion" maxlength="40" value="<?=app_escape($call['edicion']??'')?>"></div><div class="col-md-2"><?=oferta_label('Inscripción desde','Primer día habilitado para recibir preinscripciones.')?><input class="form-control" type="date" name="inscripcion_desde" value="<?=app_escape($call['inscripcion_desde']??'')?>"></div><div class="col-md-2"><?=oferta_label('Inscripción hasta','Último día habilitado para recibir preinscripciones.')?><input class="form-control" type="date" name="inscripcion_hasta" value="<?=app_escape($call['inscripcion_hasta']??'')?>"></div><div class="col-md-2"><?=oferta_label('Estado','Situación de esta convocatoria. Abierta habilita la comunicación pública de la inscripción.')?><select class="form-select" name="convocatoria_estado"><?php foreach(['programada'=>'Programada','abierta'=>'Abierta','cerrada'=>'Cerrada','finalizada'=>'Finalizada'] as $value=>$label):?><option value="<?=$value?>" <?=($call['estado']??'programada')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="col-md-2"><?=oferta_label('Cupo','Cantidad máxima de vacantes. Dejalo vacío cuando no exista un límite definido.')?><input class="form-control" type="number" name="convocatoria_cupo" min="0" max="65535" value="<?=app_escape($call['cupo']??'')?>"></div>
<div class="col-12"><hr><div class="d-flex justify-content-between align-items-center"><div><h3 class="h6 mb-1">Plan de estudios <?=oferta_ayuda('Organizá el plan por años, tramos o módulos. Cada bloque se mostrará desplegable en la página pública.','Plan de estudios')?></h3><p class="small text-secondary mb-0">Agregá las secciones necesarias y ordenalas como deben publicarse.</p></div><button class="btn btn-sm btn-outline-primary" type="button" id="offer-plan-add"><i class="bi bi-plus-lg me-1"></i>Agregar sección</button></div><div id="offer-plan-list" class="mt-3"><?php foreach($plan as $index=>$section):?><div class="offer-plan-row border rounded p-3 mb-2"><div class="row g-2"><div class="col-md-4"><label class="form-label">Título de la sección</label><input class="form-control" name="plan_titulo[]" maxlength="150" value="<?=app_escape($section['titulo'])?>" placeholder="Ej.: Primer año"></div><div class="col-md-7"><label class="form-label">Materias o contenido</label><textarea class="form-control" name="plan_contenido[]" rows="3" placeholder="Una materia o detalle por línea"><?=app_escape($section['contenido'])?></textarea></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-outline-danger w-100 js-plan-remove" type="button" title="Quitar sección"><i class="bi bi-trash"></i></button></div></div></div><?php endforeach;?></div></div>
<div class="col-12 d-flex justify-content-end gap-2"><button class="btn btn-light" type="button" onclick="$('#offers-panel').empty()">Cancelar</button><button class="btn btn-primary" type="submit">Guardar oferta</button></div>
</form></div></div>
<script>
$('#offer-admin-form').on('submit',function(e){e.preventDefault();var form=this,data=new FormData(form),button=$(form).find('[type=submit]');data.append('csrf_token',$('meta[name=csrf-token]').attr('content'));button.prop('disabled',true);$.ajax({url:'modulos/ofertas/php/app_action.php',method:'POST',data:data,processData:false,contentType:false,dataType:'json'}).done(function(response){if(!response.ok)return alert(response.message||'No se pudo guardar.');alert(response.message);offersAdminReload();}).fail(function(xhr){alert(xhr.responseJSON?xhr.responseJSON.message:(xhr.responseText||'No se pudo guardar.'));}).always(function(){button.prop('disabled',false);});});
$('#offer-image-input').on('change',function(){var file=this.files&&this.files[0];if(!file)return;var preview=document.getElementById('offer-image-preview');preview.querySelector('img').src=URL.createObjectURL(file);preview.classList.remove('is-empty');$('#offer-image-remove').removeClass('d-none');$('#offer-image-remove-value').val('0');});
$('#offer-image-remove').on('click',function(){var input=document.getElementById('offer-image-input'),preview=document.getElementById('offer-image-preview');input.value='';preview.querySelector('img').removeAttribute('src');preview.classList.add('is-empty');$(this).addClass('d-none');$('#offer-image-remove-value').val('1');});
$('#offer-plan-add').on('click',function(){$('#offer-plan-list').append('<div class="offer-plan-row border rounded p-3 mb-2"><div class="row g-2"><div class="col-md-4"><label class="form-label">Título de la sección</label><input class="form-control" name="plan_titulo[]" maxlength="150" placeholder="Ej.: Primer año"></div><div class="col-md-7"><label class="form-label">Materias o contenido</label><textarea class="form-control" name="plan_contenido[]" rows="3" placeholder="Una materia o detalle por línea"></textarea></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-outline-danger w-100 js-plan-remove" type="button" title="Quitar sección"><i class="bi bi-trash"></i></button></div></div></div>');});
$('#offer-plan-list').on('click','.js-plan-remove',function(){$(this).closest('.offer-plan-row').remove();});
document.querySelectorAll('#offer-admin-form [data-bs-toggle="tooltip"]').forEach(function(element){bootstrap.Tooltip.getOrCreateInstance(element,{container:'body',trigger:'hover focus'});});
</script>
